const VERSION='9.0.0';
const savedTheme=localStorage.getItem('bfa-theme');
document.documentElement.dataset.theme=savedTheme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');

const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const state={me:null,data:null,view:'overview',busy:0,installPrompt:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat('ar-EG').format(Number(n)||0);
const dateLabel=value=>{if(!value)return'—';const d=new Date(String(value).replace(' ','T')+'Z');return Number.isNaN(d.getTime())?esc(value):new Intl.DateTimeFormat('ar-EG',{dateStyle:'medium',timeStyle:'short'}).format(d)};
const contentMap={lectures:'المحاضرات',summaries:'الملخصات',sections:'السكاشن',books:'الكتب',assignments:'الواجبات',exams:'الامتحانات السابقة',recordings:'التسجيلات',links:'روابط مهمة'};
const roleMap={owner:'المالك',admin:'مدير',editor:'محرر'};
const contentLabel=v=>contentMap[v]||v||'أخرى';
const contentOptions=(selected='')=>Object.entries(contentMap).map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('');
const statusBadge=v=>`<span class="badge ${v==='published'||v==='active'?'success':'neutral'}">${v==='published'?'منشور':v==='active'?'نشط':'مخفي'}</span>`;
const linkBadge=v=>`<span class="url-status ${v==='ok'?'ok':v==='error'?'error':'unknown'}">${v==='ok'?'سليم':v==='error'?'مشكلة':'غير مفحوص'}</span>`;
const isAdmin=()=>['owner','admin'].includes(state.me?.role);
const isOwner=()=>state.me?.role==='owner';

