  $('#publicCatalog').innerHTML=items.length?[...grouped.values()].map((group,index)=>`<section class="subject-card premium-subject" style="--subject-index:${index}"><header class="subject-header"><div class="subject-heading-wrap"><span class="subject-icon">${icon('book')}</span><div><span class="subject-code">${esc(group[0].subject_code||'COURSE')}</span><h3>${esc(group[0].subject_name)}</h3><p>${[group[0].study_level,group[0].semester,group[0].department].filter(Boolean).map(esc).join(' • ')}</p></div></div><span class="subject-count-pill">${num(group.length)} ملف</span></header><div class="resource-list">${group.map(publicResourceRow).join('')}</div></section>`).join(''):`<div class="empty-state premium-empty"><div class="empty-icon">${icon(state.publicScope==='favorites'?'heart':'search')}</div><h3>لا توجد نتائج</h3><p>${activeSubject?'لا توجد ملفات مطابقة داخل هذه المادة.':'جرّب تغيير البحث أو الفلاتر.'}</p><button class="btn-ghost" data-reset-public>إعادة ضبط البحث</button></div>`;
  $('[data-reset-public]')?.addEventListener('click',()=>{state.publicSubject=null;state.publicScope='all';['publicSearch','levelFilter','semesterFilter','departmentFilter','typeFilter','tagFilter'].forEach(id=>{const el=$('#'+id);if(el)el.value=''});renderPublicCatalog()});
