function publicResourceRow(r){const favorite=getLocalList('bfa-favorites').map(Number).includes(+r.id),tags=String(r.tags||'').split(',').map(x=>x.trim()).filter(Boolean);return`<article class="resource-row premium-resource"><div class="resource-icon type-${esc(r.content_type||'links')}">${icon('file')}</div><div class="resource-info"><div class="resource-title-line"><h4>${r.pinned?'<span class="pin-dot">📌</span> ':''}${esc(r.title)}</h4>${r.expires_at?`<span class="badge warning">حتى ${esc(String(r.expires_at).slice(0,10))}</span>`:''}</div><p>${esc(r.description||r.lecture_name||contentLabel(r.content_type))}</p><div class="resource-meta"><span>${contentLabel(r.content_type)}</span><span>${esc(r.type||'رابط')}</span><span>${sizeLabel(r.file_size)}</span><span>${num(r.downloads)} فتح</span></div>${tags.length?`<div class="tag-row">${tags.slice(0,4).map(t=>`<button class="tag" data-public-tag="${esc(t)}">#${esc(t)}</button>`).join('')}</div>`:''}</div><div class="resource-actions"><button class="icon-btn btn-ghost ${favorite?'favorite-on':''}" data-favorite="${r.id}" title="المفضلة" aria-label="المفضلة">${icon('heart')}</button><button class="icon-btn btn-ghost resource-qr" data-qr="${r.id}" title="QR" aria-label="QR">${icon('qr')}</button><button class="btn open-resource-btn" data-links="${r.id}">${icon('external')} فتح الملف</button></div></article>`}
function bindPublicRows(){$$('[data-favorite]').forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.favorite));$$('[data-qr]').forEach(b=>b.onclick=()=>showQR(b.dataset.qr));$$('[data-links]').forEach(b=>b.onclick=()=>showResourceLinks(Number(b.dataset.links),false));$$('[data-public-tag]').forEach(b=>b.onclick=()=>{$('#tagFilter').value=b.dataset.publicTag;renderPublicCatalog()})}
function showQR(id){const r=state.data?.resources?.find(x=>+x.id===+id);if(!r)return;const link=`${location.origin}/api/resource/${id}`,src=`https://quickchart.io/qr?size=300&margin=2&text=${encodeURIComponent(link)}`;openModal({title:'QR للملف',body:`<div class="qr-box"><img src="${src}" alt="QR"><h3>${esc(r.title)}</h3><p class="muted">امسح الكود لفتح الرابط الأساسي.</p><code>${esc(link)}</code></div>`,foot:`<button class="btn-ghost" data-copy-link="${esc(link)}">${icon('copy')} نسخ الرابط</button><button class="btn" data-open-primary="${id}">${icon('external')} فتح</button>`,onReady:layer=>{$('[data-copy-link]',layer).onclick=()=>navigator.clipboard.writeText(link).then(()=>toast('تم نسخ الرابط','success'));$('[data-open-primary]',layer).onclick=()=>openResource(id)}})}
