function renderSubjects(){setAdminTitle('المواد','إدارة الهيكل الأكاديمي والمواد');const items=filtered(state.data.subjects,['name','code','department','study_level','semester']);$('#adminView').innerHTML=toolbar('إضافة مادة','addSubject')+`<section class="panel data-list"><div class="data-row header"><span>المادة</span><span>المستوى</span><span>الفصل</span><span>الحالة</span><span>إجراءات</span></div>${items.map(s=>`<div class="data-row"><div class="main-cell"><b>${esc(s.name)}</b><small>${esc(s.code)} • ${esc(s.department)}</small></div><span>${esc(s.study_level||'—')}</span><span>${esc(s.semester||'—')}</span>${statusBadge(s.status)}<div class="row-actions"><button class="icon-btn btn-ghost small" data-edit-subject="${s.id}">${icon('edit')}</button><button class="icon-btn btn-danger small" data-trash-subject="${s.id}">${icon('trash')}</button></div></div>`).join('')||'<div class="admin-empty">لا توجد مواد.</div>'}</section>`;$('#addSubject').onclick=()=>subjectModal();bindSearch(renderSubjects);$$('[data-edit-subject]').forEach(b=>b.onclick=()=>subjectModal(state.data.subjects.find(x=>+x.id===+b.dataset.editSubject)));$$('[data-trash-subject]').forEach(b=>b.onclick=()=>trashEntity('subject',b.dataset.trashSubject,'المادة'))}
function subjectModal(item=null){const edit=!!item;openModal({title:edit?'تعديل المادة':'إضافة مادة',body:`<form id="subjectForm" class="form"><div class="form-grid"><label class="form-label"><span>اسم المادة</span><input name="name" value="${esc(item?.name||'')}" required></label><label class="form-label"><span>الكود</span><input name="code" value="${esc(item?.code||'')}" required></label><label class="form-label"><span>القسم</span><input name="department" value="${esc(item?.department||'Business')}"></label><label class="form-label"><span>العام الدراسي</span><input name="academic_year" value="${esc(item?.academic_year||'')}"></label><label class="form-label"><span>المستوى</span><input name="study_level" value="${esc(item?.study_level||'')}"></label><label class="form-label"><span>الفصل</span><input name="semester" value="${esc(item?.semester||'')}"></label><label class="form-label"><span>الحالة</span><select name="status"><option value="published" ${item?.status!=='hidden'?'selected':''}>منشور</option><option value="hidden" ${item?.status==='hidden'?'selected':''}>مخفي</option></select></label></div></form>`,foot:`<button class="btn-ghost" data-close-modal>إلغاء</button><button class="btn" id="saveSubject">حفظ</button>`,onReady:layer=>{$('#saveSubject',layer).onclick=async()=>{const f=$('#subjectForm',layer);if(!f.reportValidity())return;try{await api(edit?`/admin/subject/${item.id}`:'/admin/subject',{method:edit?'PUT':'POST',body:JSON.stringify(values(f))});closeModal();toast('تم حفظ المادة','success');await refreshDashboard();renderSubjects()}catch(e){toast(e.message,'error')}}}})}
function renderResources(){setAdminTitle('الملفات والروابط','روابط خارجية فقط — أساسي + رابطان احتياطيان');const items=filtered(state.data.resources,['title','subject_name','lecture_name','tags','type']);const extra=`<button class="btn-ghost" id="checkVisible">${icon('refresh')} فحص الظاهر</button>`;$('#adminView').innerHTML=toolbar('إضافة رابط','addResource','plus',extra)+`<section class="panel data-list"><div class="data-row header"><span>الملف</span><span>المادة</span><span>الرابط</span><span>الحالة</span><span>إجراءات</span></div>${items.map(r=>`<div class="data-row"><div class="main-cell"><b>${r.pinned?'📌 ':''}${esc(r.title)}</b><small>${esc(r.type)} • ${contentLabel(r.content_type)} • ${sizeLabel(r.file_size)}</small></div><span>${esc(r.subject_name)}</span><span>${linkBadge(r.link_status)}</span>${statusBadge(r.status)}<div class="row-actions"><button class="icon-btn btn-ghost small" data-open-links="${r.id}" title="الروابط">${icon('link')}</button><button class="icon-btn btn-ghost small" data-check-link="${r.id}" title="فحص">${icon('refresh')}</button><button class="icon-btn btn-ghost small" data-edit-resource="${r.id}">${icon('edit')}</button><button class="icon-btn btn-danger small" data-trash-resource="${r.id}">${icon('trash')}</button></div></div>`).join('')||'<div class="admin-empty">لا توجد ملفات.</div>'}</section>`;$('#addResource').onclick=()=>resourceModal();bindSearch(renderResources);$$('[data-open-links]').forEach(b=>b.onclick=()=>showResourceLinks(+b.dataset.openLinks));$$('[data-check-link]').forEach(b=>b.onclick=()=>checkLink(+b.dataset.checkLink,b));$$('[data-edit-resource]').forEach(b=>b.onclick=()=>resourceModal(state.data.resources.find(x=>+x.id===+b.dataset.editResource)));$$('[data-trash-resource]').forEach(b=>b.onclick=()=>trashEntity('resource',b.dataset.trashResource,'الملف'));$('#checkVisible').onclick=async()=>{for(const r of items.slice(0,25))await checkLink(r.id,null,true);toast('انتهى فحص الروابط الظاهرة','success');await refreshDashboard();renderResources()}}
function resourceModal(item=null){const edit=!!item,subjects=state.data.subjects;openModal({title:edit?'تعديل الملف والرابط':'إضافة ملف كرابط خارجي',wide:true,body:`<form id="resourceForm" class="form"><div class="notice">NO R2: لا يتم رفع أي ملف إلى Cloudflare. أدخل رابط HTTPS عام ويمكنك إضافة رابطين احتياطيين.</div><div class="form-grid"><label class="form-label"><span>المادة</span><select name="subject_id" required><option value="">اختر المادة</option>${subjects.map(s=>`<option value="${s.id}" ${+item?.subject_id===+s.id?'selected':''}>${esc(s.name)} — ${esc(s.code)}</option>`).join('')}</select></label><label class="form-label"><span>العنوان</span><input name="title" value="${esc(item?.title||'')}" required></label><label class="form-label full"><span>الرابط الأساسي HTTPS</span><input name="resource_url" type="url" value="${esc(item?.resource_url||'')}" placeholder="https://drive.google.com/..." required></label><label class="form-label full"><span>الرابط الاحتياطي 1</span><input name="mirror_url_1" type="url" value="${esc(item?.mirror_url_1||'')}" placeholder="اختياري"></label><label class="form-label full"><span>الرابط الاحتياطي 2</span><input name="mirror_url_2" type="url" value="${esc(item?.mirror_url_2||'')}" placeholder="اختياري"></label><label class="form-label"><span>النوع</span><input name="type" value="${esc(item?.type||'PDF')}" placeholder="PDF / ZIP / Video"></label><label class="form-label"><span>تصنيف المحتوى</span><select name="content_type">${contentOptions(item?.content_type||'lectures')}</select></label><label class="form-label"><span>اسم المحاضرة</span><input name="lecture_name" value="${esc(item?.lecture_name||'')}"></label><label class="form-label"><span>الحجم بالبايت</span><input name="file_size" type="number" min="0" value="${Number(item?.file_size)||0}"></label><label class="form-label full"><span>Tags — مفصولة بفواصل</span><input name="tags" value="${esc(item?.tags||'')}" placeholder="revision, important, final"></label><label class="form-label"><span>ينتهي الرابط في</span><input name="expires_at" type="datetime-local" value="${esc(toLocalInput(item?.expires_at))}"></label><label class="form-label"><span>الحالة</span><select name="status"><option value="published" ${item?.status!=='hidden'?'selected':''}>منشور</option><option value="hidden" ${item?.status==='hidden'?'selected':''}>مخفي</option></select></label><label class="form-label full"><span>الوصف</span><textarea name="description">${esc(item?.description||'')}</textarea></label></div><label class="check-line"><input name="pinned" type="checkbox" ${item?.pinned?'checked':''}> تثبيت الملف أعلى النتائج</label></form>`,foot:`<button class="btn-ghost" data-close-modal>إلغاء</button><button class="btn" id="saveResource">حفظ</button>`,onReady:layer=>{$('#saveResource',layer).onclick=async()=>{const f=$('#resourceForm',layer);if(!f.reportValidity())return;const x=values(f);x.pinned=f.elements.pinned.checked?1:0;try{await api(edit?`/admin/resource/${item.id}`:'/admin/resource',{method:edit?'PUT':'POST',body:JSON.stringify(x)});closeModal();toast('تم حفظ الملف','success');await refreshDashboard();renderResources()}catch(e){toast(e.message,'error')}}}})}
async function checkLink(id,button=null,silent=false){if(button)button.disabled=true;try{const d=await api('/admin/link-check',{method:'POST',body:JSON.stringify({id})});if(!silent)openModal({title:'نتيجة فحص الروابط',body:`<div class="check-results">${d.checks.map(c=>`<div class="check-result ${c.status}"><b>${c.name==='primary'?'الأساسي':c.name==='mirror1'?'الاحتياطي 1':'الاحتياطي 2'}</b><span>${c.status==='ok'?'سليم':'مشكلة'} • HTTP ${c.httpStatus||'—'}</span></div>`).join('')}</div>`});return d}catch(e){if(!silent)toast(e.message,'error')}finally{if(button)button.disabled=false}}
function renderAnnouncements(){setAdminTitle('الإعلانات','نشر وجدولة الإعلانات للطلاب');const items=filtered(state.data.announcements,['title','content','priority']);$('#adminView').innerHTML=toolbar('إعلان جديد','addAnnouncement')+`<section class="panel data-list"><div class="data-row header"><span>الإعلان</span><span>الأولوية</span><span>الجدولة</span><span>الحالة</span><span>إجراءات</span></div>${items.map(a=>`<div class="data-row"><div class="main-cell"><b>${a.pinned?'📌 ':''}${esc(a.title)}</b><small>${esc(a.content)}</small></div><span>${a.priority==='high'?'مهم':'عادي'}</span><span>${a.starts_at?dateLabel(a.starts_at):'فوري'}</span>${statusBadge(a.status)}<div class="row-actions"><button class="icon-btn btn-ghost small" data-edit-ann="${a.id}">${icon('edit')}</button><button class="icon-btn btn-danger small" data-trash-ann="${a.id}">${icon('trash')}</button></div></div>`).join('')||'<div class="admin-empty">لا توجد إعلانات.</div>'}</section>`;$('#addAnnouncement').onclick=()=>announcementModal();bindSearch(renderAnnouncements);$$('[data-edit-ann]').forEach(b=>b.onclick=()=>announcementModal(state.data.announcements.find(x=>+x.id===+b.dataset.editAnn)));$$('[data-trash-ann]').forEach(b=>b.onclick=()=>trashEntity('announcement',b.dataset.trashAnn,'الإعلان'))}
function announcementModal(item=null){const edit=!!item;openModal({title:edit?'تعديل الإعلان':'إعلان جديد',body:`<form id="annForm" class="form"><label class="form-label"><span>العنوان</span><input name="title" value="${esc(item?.title||'')}" required></label><label class="form-label"><span>المحتوى</span><textarea name="content" required>${esc(item?.content||'')}</textarea></label><div class="form-grid"><label class="form-label"><span>الأولوية</span><select name="priority"><option value="normal">عادي</option><option value="high" ${item?.priority==='high'?'selected':''}>مهم</option></select></label><label class="form-label"><span>الحالة</span><select name="status"><option value="published">منشور</option><option value="hidden" ${item?.status==='hidden'?'selected':''}>مخفي</option></select></label><label class="form-label"><span>البداية</span><input name="starts_at" type="datetime-local" value="${esc(toLocalInput(item?.starts_at))}"></label><label class="form-label"><span>النهاية</span><input name="ends_at" type="datetime-local" value="${esc(toLocalInput(item?.ends_at))}"></label></div><label class="check-line"><input name="pinned" type="checkbox" ${item?.pinned?'checked':''}> تثبيت الإعلان</label></form>`,foot:`<button class="btn-ghost" data-close-modal>إلغاء</button><button class="btn" id="saveAnn">حفظ</button>`,onReady:layer=>{$('#saveAnn',layer).onclick=async()=>{const f=$('#annForm',layer);if(!f.reportValidity())return;const x=values(f);x.pinned=f.elements.pinned.checked?1:0;try{await api(edit?`/admin/announcement/${item.id}`:'/admin/announcement',{method:edit?'PUT':'POST',body:JSON.stringify(x)});closeModal();toast('تم حفظ الإعلان','success');await refreshDashboard();renderAnnouncements()}catch(e){toast(e.message,'error')}}}})}
function parseCsv(text){const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return[];const split=line=>{const out=[];let cur='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){cur+='"';i++}else quote=!quote}else if(c===','&&!quote){out.push(cur.trim());cur=''}else cur+=c}out.push(cur.trim());return out};const headers=split(lines[0]).map(x=>x.toLowerCase());return lines.slice(1).map(line=>Object.fromEntries(headers.map((h,i)=>[h,split(line)[i]||''])))}
function renderImport(){setAdminTitle('استيراد جماعي','أضف حتى 200 رابط دفعة واحدة');$('#adminView').innerHTML=`<section class="panel settings-card"><h2>CSV / لصق مباشر</h2><p class="muted">أول سطر يجب أن يحتوي أسماء الأعمدة. الحد الأدنى: <code>subject_code,title,url</code></p><div class="notice code-notice">subject_code,title,url,type,content_type,tags,mirror_url_1,mirror_url_2<br>ACC101,Chapter 1,https://example.com/file.pdf,PDF,lectures,"chapter1, important",,</div><textarea id="bulkCsv" class="bulk-textarea" placeholder="الصق CSV هنا..."></textarea><div class="row-flex import-actions"><label class="btn-ghost file-picker">${icon('upload')} اختيار CSV<input id="bulkFile" type="file" accept=".csv,text/csv" hidden></label><button class="btn" id="bulkImport">${icon('import')} استيراد الآن</button></div><div id="bulkPreview"></div></section>`;$('#bulkCsv').addEventListener('input',renderBulkPreview);$('#bulkFile').onchange=async e=>{const f=e.target.files?.[0];if(f){$('#bulkCsv').value=await f.text();renderBulkPreview()}};$('#bulkImport').onclick=bulkImport;renderBulkPreview()}
function renderBulkPreview(){const text=$('#bulkCsv')?.value||'',items=parseCsv(text),box=$('#bulkPreview');if(!box)return;box.innerHTML=items.length?`<div class="import-preview"><b>${num(items.length)} عنصر جاهز</b><small>سيتم التحقق من المادة والروابط قبل إدخال أي شيء.</small>${items.slice(0,5).map(x=>`<div>${esc(x.subject_code||x.subject_id)} • ${esc(x.title)} • ${esc(x.url||x.resource_url)}</div>`).join('')}</div>`:'<p class="muted top-gap">لا توجد بيانات بعد.</p>'}
async function bulkImport(){const items=parseCsv($('#bulkCsv').value);if(!items.length)return toast('ألصق بيانات CSV أولًا','error');try{const d=await api('/admin/resources/bulk',{method:'POST',body:JSON.stringify({items})});toast(`تم استيراد ${d.imported} ملف`,'success');await refreshDashboard();state.view='resources';dashboard()}catch(e){toast(e.message,'error')}}
async function trashEntity(type,id,label){const ok=await confirmAction({title:`نقل ${label} إلى السلة`,message:'يمكن استرجاع العنصر لاحقًا من سلة المحذوفات.',confirmText:'نقل إلى السلة',danger:true});if(!ok)return;try{await api(`/admin/${type}/${id}`,{method:'DELETE'});toast('تم النقل إلى سلة المحذوفات','success');await refreshDashboard();renderAdminView()}catch(e){toast(e.message,'error')}}
async function renderTrash(){setAdminTitle('سلة المحذوفات','استرجاع العناصر أو حذفها نهائيًا');try{const d=await api('/admin/trash');const groups=[['subject','المواد',d.subjects],['resource','الملفات',d.resources],['announcement','الإعلانات',d.announcements]];$('#adminView').innerHTML=`<div class="stack">${groups.map(([type,title,items])=>`<section class="panel"><header class="panel-head"><h2>${title}</h2><span class="badge neutral">${items.length}</span></header><div class="trash-list">${items.map(x=>`<div class="trash-item"><div><b>${esc(x.title)}</b><small>${esc(x.subtitle||'')} • ${dateLabel(x.deleted_at)}</small></div><div class="row-actions"><button class="btn-soft small" data-restore="${type}:${x.id}">${icon('restore')} استرجاع</button><button class="btn-danger small" data-permanent="${type}:${x.id}">${icon('trash')} حذف نهائي</button></div></div>`).join('')||'<div class="admin-empty">فارغة</div>'}</div></section>`).join('')}</div>`;$$('[data-restore]').forEach(b=>b.onclick=()=>trashRestore(...b.dataset.restore.split(':')));$$('[data-permanent]').forEach(b=>b.onclick=()=>trashPermanent(...b.dataset.permanent.split(':')))}catch(e){toast(e.message,'error')}}
async function trashRestore(type,id){try{await api(`/admin/trash/${type}/${id}/restore`,{method:'POST'});toast('تم الاسترجاع','success');await refreshDashboard();renderTrash()}catch(e){toast(e.message,'error')}}
async function trashPermanent(type,id){const ok=await confirmAction({title:'حذف نهائي',message:'لن تستطيع استرجاع هذا العنصر بعد الحذف.',confirmText:'حذف نهائي',danger:true});if(!ok)return;try{await api(`/admin/trash/${type}/${id}`,{method:'DELETE'});toast('تم الحذف نهائيًا','success');await refreshDashboard();renderTrash()}catch(e){toast(e.message,'error')}}
async function renderTeam(){setAdminTitle('فريق الإدارة','Owner يتحكم في المديرين والمحررين');try{const d=await api('/admin/team');$('#adminView').innerHTML=`${toolbar('إضافة عضو','addMember')}<section class="panel data-list"><div class="data-row header"><span>العضو</span><span>الدور</span><span>منذ</span><span>الحالة</span><span>إجراءات</span></div>${d.items.map(x=>`<div class="data-row"><div class="main-cell"><b>${esc(x.name)}</b><small>${esc(x.email)}</small></div><span>${roleMap[x.role]}</span><span>${dateLabel(x.created_at)}</span><span class="badge ${x.status==='active'?'success':'danger'}">${x.status==='active'?'نشط':'معطّل'}</span><div class="row-actions">${x.role==='owner'?'—':`<button class="btn-ghost small" data-member="${x.id}" data-role="${x.role}" data-status="${x.status}">${icon('edit')} تعديل</button>`}</div></div>`).join('')}</section>`;$('#addMember').onclick=memberModal;$$('[data-member]').forEach(b=>b.onclick=()=>memberEditModal(b.dataset.member,b.dataset.role,b.dataset.status))}catch(e){toast(e.message,'error')}}
function memberModal(){openModal({title:'إضافة عضو إدارة',body:`<form id="memberForm" class="form"><input name="name" placeholder="الاسم" required><input name="email" type="email" placeholder="البريد" required>${passwordField('password','كلمة مرور مؤقتة — 10 أحرف','new-password')}<label class="form-label"><span>الدور</span><select name="role"><option value="editor">محرر — إدارة المحتوى</option><option value="admin">مدير — محتوى + إعدادات ونسخ احتياطية</option></select></label></form>`,foot:`<button class="btn-ghost" data-close-modal>إلغاء</button><button class="btn" id="saveMember">إضافة</button>`,onReady:layer=>{bindPasswordToggles(layer);$('#saveMember',layer).onclick=async()=>{const f=$('#memberForm',layer);if(!f.reportValidity())return;try{await api('/admin/team',{method:'POST',body:JSON.stringify(values(f))});closeModal();toast('تم إضافة العضو','success');renderTeam()}catch(e){toast(e.message,'error')}}}})}
function memberEditModal(id,role,status){openModal({title:'تعديل صلاحيات العضو',body:`<form id="memberEdit" class="form"><label class="form-label"><span>الدور</span><select name="role"><option value="editor" ${role==='editor'?'selected':''}>محرر</option><option value="admin" ${role==='admin'?'selected':''}>مدير</option></select></label><label class="form-label"><span>الحالة</span><select name="status"><option value="active" ${status==='active'?'selected':''}>نشط</option><option value="disabled" ${status==='disabled'?'selected':''}>معطّل</option></select></label></form>`,foot:`<button class="btn-ghost" data-close-modal>إلغاء</button><button class="btn" id="saveMemberEdit">حفظ</button>`,onReady:layer=>{$('#saveMemberEdit',layer).onclick=async()=>{try{await api(`/admin/team/${id}`,{method:'PATCH',body:JSON.stringify(values($('#memberEdit',layer)))});closeModal();toast('تم تحديث العضو','success');renderTeam()}catch(e){toast(e.message,'error')}}}})}
async function renderSettings(){setAdminTitle('الإعدادات','الهوية والصيانة والنسخ الاحتياطية');const publicData=await api('/public'),s=publicData.settings||{};$('#adminView').innerHTML=`<div class="settings-grid"><section class="panel settings-card"><h2>هوية الموقع</h2><form id="settingsForm" class="form"><label class="form-label"><span>اسم الموقع</span><input name="site_name" value="${esc(s.site_name||'Business For All')}" required></label><label class="form-label"><span>الوصف</span><textarea name="site_description">${esc(s.site_description||'')}</textarea></label><div class="form-grid"><label class="form-label"><span>العام الدراسي</span><input name="academic_year" value="${esc(s.academic_year||'')}"></label><label class="form-label"><span>شارة الرئيسية</span><input name="hero_badge" value="${esc(s.hero_badge||'')}"></label></div><label class="form-label"><span>التذييل</span><input name="footer_text" value="${esc(s.footer_text||'')}"></label><div class="maintenance-box"><label class="check-line"><input name="maintenance_mode" type="checkbox" ${s.maintenance_mode==='1'?'checked':''}> تفعيل وضع الصيانة للطلاب</label><label class="form-label"><span>رسالة الصيانة</span><textarea name="maintenance_message">${esc(s.maintenance_message||'')}</textarea></label></div><button class="btn" type="submit">حفظ الإعدادات</button></form></section><section class="stack"><div class="panel settings-card"><h2>النسخ الاحتياطية</h2><p class="muted">JSON يشمل المحتوى والإعدادات وسلة المحذوفات، ولا يشمل كلمات مرور الإدارة.</p><div class="action-block"><div><b>تصدير Backup</b><small>نسخة قابلة للاستعادة.</small></div><button class="btn-soft" id="downloadBackup">${icon('download')} تنزيل</button></div><div class="action-block"><div><b>استعادة Backup</b><small>يستبدل بيانات المحتوى.</small></div><button class="btn-ghost" id="restoreBackup">${icon('upload')} استعادة</button><input id="restoreFile" type="file" accept=".json,application/json" hidden></div></div><div class="panel settings-card"><h2>بنية النسخة</h2><div class="summary-row"><span>Database</span><b>D1</b></div><div class="summary-row"><span>Files</span><b>External HTTPS Links</b></div><div class="summary-row"><span>R2</span><b class="success-text">غير مستخدم</b></div><div class="summary-row"><span>Version</span><b>${VERSION}</b></div></div></section></div>`;$('#settingsForm').onsubmit=saveSettings;$('#downloadBackup').onclick=downloadBackup;$('#restoreBackup').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=restoreBackup}
async function saveSettings(e){e.preventDefault();const x=values(e.target);x.maintenance_mode=e.target.elements.maintenance_mode.checked?1:0;try{await api('/admin/settings',{method:'PUT',body:JSON.stringify(x)});toast('تم حفظ الإعدادات','success')}catch(err){toast(err.message,'error')}}
async function downloadBackup(){try{const d=await api('/admin/backup'),blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`business-for-all-v8-no-r2-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}catch(e){toast(e.message,'error')}}
async function restoreBackup(e){const file=e.target.files?.[0];if(!file)return;let data;try{data=JSON.parse(await file.text())}catch{return toast('ملف JSON غير صالح','error')}const ok=await confirmAction({title:'استعادة النسخة',message:'سيتم استبدال بيانات المحتوى الحالية.',confirmText:'استعادة',danger:true});if(!ok)return;try{await api('/admin/restore',{method:'POST',body:JSON.stringify(data)});toast('تمت الاستعادة','success');await refreshDashboard();renderSettings()}catch(err){toast(err.message,'error')}finally{e.target.value=''}}
function renderSecurity(){setAdminTitle('الأمان','كلمة المرور والجلسات');$('#adminView').innerHTML=`<div class="settings-grid"><section class="panel settings-card"><h2>تغيير كلمة المرور</h2><form id="passwordForm" class="form"><label class="form-label"><span>الحالية</span>${passwordField('current','كلمة المرور الحالية')}</label><label class="form-label"><span>الجديدة</span>${passwordField('next','كلمة المرور الجديدة','new-password')}</label><label class="form-label"><span>التأكيد</span>${passwordField('confirm','تأكيد الجديدة','new-password')}</label><button class="btn" type="submit">${icon('lock')} تغيير كلمة المرور</button></form></section><section class="panel settings-card danger-zone"><h2>الجلسات</h2><p class="muted">أنهِ كل جلسات هذا الحساب على جميع الأجهزة.</p><button class="btn-danger" id="revokeSessions">${icon('logout')} إنهاء جميع الجلسات</button></section></div>`;bindPasswordToggles($('#adminView'));$('#passwordForm').onsubmit=changePassword;$('#revokeSessions').onclick=revokeSessions}
async function changePassword(e){e.preventDefault();const x=values(e.target);if(x.next!==x.confirm)return toast('كلمتا المرور غير متطابقتين','error');try{const d=await api('/admin/password',{method:'PUT',body:JSON.stringify(x)});toast(d.message,'success');state.me=null;login()}catch(err){toast(err.message,'error')}}
async function revokeSessions(){const ok=await confirmAction({title:'إنهاء الجلسات',message:'سيتم تسجيل خروج هذا الحساب من كل الأجهزة.',confirmText:'إنهاء',danger:true});if(!ok)return;try{await api('/admin/sessions/revoke',{method:'POST'});state.me=null;login()}catch(e){toast(e.message,'error')}}
async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}state.me=null;location.hash='';publicSite()}
async function installApp(){if(!state.installPrompt)return;state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;$('#installApp')?.classList.add('hidden');toast('تم إرسال طلب التثبيت','success')}

window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;$('#installApp')?.classList.remove('hidden')});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
document.addEventListener('click',e=>{if(e.target.closest('[data-close-modal]'))closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').classList.contains('hidden'))closeModal()});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#admin')&&state.me)dashboard();else if(!location.hash)publicSite()});
start();
